#!/usr/bin/env python3
"""Guarded COSMOS v9.4.4: Timeline, image fit and locations. Frontend only.
This script only changes cosmos-next.html when --mode apply is specified.
"""
import argparse,base64,hashlib,json,sys,zlib
from pathlib import Path
SOURCE_SHA='ae8a68b4fa51be911885d1db75481625efe0d2367adc224b3f0ef10f43d1f7fe'
TARGET_SHA='6d52dde9e0dae3afb483020ea11051b74778064ce5afde4bdfe9944e7689172a'
PATCH_B64=''

def digest(s):return hashlib.sha256(s.encode('utf-8')).hexdigest()
def main():
 parser=argparse.ArgumentParser()
 parser.add_argument('--mode',choices=('validate','apply'),required=True)
 a=parser.parse_args()
 f=Path('cosmos-next.html')
 if not f.is_file():sys.exit('STOP: cosmos-next.html not found in repository root.')
 old=f.read_text(encoding='utf-8')
 h=digest(old)
 if h==TARGET_SHA:
  print('Already on COSMOS v9.4.4. Nothing to modify.')
  return
 if h!=SOURCE_SHA:
  sys.exit('STOP: frontend has diverged from the expected v9.4.3 source. No file changed. Current SHA256: '+h)
 changes=json.loads(zlib.decompress(base64.b64decode(PATCH_B64)).decode('utf-8'))
 lines=old.splitlines(keepends=True)
 for i,j,text in reversed(changes):lines[i:j]=[text]
 output=''.join(lines)
 if digest(output)!=TARGET_SHA or 'cosmos944TimeRailPhotoLocation' not in output or 'cosmos944PlaceSearch' not in output:
  sys.exit('STOP: checksum or feature verification failed.')
 print('v9.4.4 guarded patch verified: timeline/photo/location controls.')
 if a.mode=='validate':print('VALIDATE PASSED; no files changed.')
 else:
  f.write_text(output,encoding='utf-8')
  print('APPLY PASSED; updated cosmos-next.html only.')
if __name__=='__main__':main()
